manifest = args["manifest"]
mt = get(args, "max_tokens", 8000)

if type(manifest) != "string" or len(manifest) == 0:
  error("working context: manifest must be a non-empty string")
if type(mt) != "int" or mt < 1:
  error("working context: max_tokens must be a positive integer")
try:
  parsed = json_parse(manifest)
catch:
  error("working context: manifest is not valid JSON")
if type(parsed) != "map" or not has_key(parsed, "r") or type(parsed["r"]) != "list":
  error("working context: manifest must contain an r reference list")

refs = []
for ref in parsed["r"]:
  if type(ref) != "map":
    error("working context: manifest reference must be an object")
  if not has_key(ref, "f") or type(ref["f"]) != "string" or len(ref["f"]) == 0:
    error("working context: manifest reference requires a non-empty string f")
  clean = {f: ref["f"]}
  if has_key(ref, "s") and type(ref["s"]) == "string" and len(ref["s"]) > 0:
    clean = merge(clean, {s: ref["s"]})
  if has_key(ref, "role") and type(ref["role"]) == "string" and len(ref["role"]) > 0:
    clean = merge(clean, {role: ref["role"]})
  if has_key(ref, "x") and type(ref["x"]) == "list" and len(ref["x"]) > 0:
    clean = merge(clean, {x: ref["x"]})
  refs = refs + [clean]
if len(refs) == 0:
  error("working context: empty working set")
if len(refs) > 128:
  error("working context: too many references (" + str(len(refs)) + "); maximum is 128")

built = {t: get(parsed, "t", ""), v: "1.0", r: refs}
res = lci.context(operation:"load", from_string: json_stringify(built), max_tokens: mt)
if type(res) == "map":
  if has_key(res, "available") and res["available"] == false:
    error("working context: index unavailable: " + get(res, "reason", "") + " (" + get(res, "hint", "") + ")")
  if has_key(res, "success") and res["success"] == false:
    error("working context: context load failed: " + get(res, "error", ""))
res

terms = args["terms"]
filters = get(args, "files", [])
mt = get(args, "max_tokens", 8000)

if type(terms) != "list" or len(terms) < 1 or len(terms) > 8:
  error("working context: terms must be a list of 1 to 8 search terms")
if type(mt) != "int" or mt < 1:
  error("working context: max_tokens must be a positive integer")
if type(filters) != "list":
  error("working context: files filter must be a list of strings")
for flt in filters:
  if type(flt) != "string" or len(flt) == 0:
    error("working context: files filter entries must be non-empty strings")
seen_terms = []
for t in terms:
  if type(t) != "string" or len(t) == 0:
    error("working context: terms must each be a non-empty string")
  if t in seen_terms:
    error("working context: duplicate terms entry " + t)
  seen_terms = seen_terms + [t]

cand = {}
search_errors = []
for term in terms:
  try:
    res = lci.search(pattern: term, max: 50, output: "line")
    if type(res) == "map" and has_key(res, "available") and res["available"] == false:
      search_errors = search_errors + [{term: term, error: "index unavailable: " + get(res, "reason", "") + " (" + get(res, "hint", "") + ")"}]
    elif type(res) == "map" and has_key(res, "success") and res["success"] == false:
      search_errors = search_errors + [{term: term, error: get(res, "error", "search failed")}]
    else:
      for g in get(res, "results", []):
        file = get(g, "file", "")
        if len(filters) > 0:
          kept = false
          for flt in filters:
            if file == flt or endswith(file, "/" + flt) or endswith(file, flt):
              kept = true
          if not kept:
            continue
        for h in get(g, "hits", []):
          sym = get(h, "sym", "")
          if sym == "":
            continue
          key = file + "\u001f" + sym
          sc = get(h, "score", 0)
          ln = get(h, "line", 0)
          if has_key(cand, key):
            prev = cand[key]
            if sc > prev["score"] or (sc == prev["score"] and ln < prev["line"]):
              cand = merge(cand, dict([[key, {f: file, s: sym, line: ln, score: sc}]]))
          else:
            cand = merge(cand, dict([[key, {f: file, s: sym, line: ln, score: sc}]]))
  catch:
    search_errors = search_errors + [{term: term, error: "search call failed"}]

by_sort = {}
sort_keys = []
for key in keys(cand):
  c = cand[key]
  inv = 1000000000000 - int(c["score"] * 1000000)
  sk = pad_left(str(inv), 16, "0") + "\u001f" + c["f"] + "\u001f" + c["s"] + "\u001f" + pad_left(str(c["line"]), 9, "0")
  by_sort = merge(by_sort, dict([[sk, c]]))
  sort_keys = sort_keys + [sk]

total = len(by_sort)
selected = []
for sk in sorted(sort_keys):
  if len(selected) < 16:
    selected = selected + [by_sort[sk]]
omitted = total - len(selected)
rank_selected = []
for c in selected:
  rank_selected = rank_selected + [{f: c["f"], s: c["s"], score: c["score"]}]
meta = {terms: terms, candidates: total, selected: rank_selected, omitted: omitted, search_errors: search_errors, empty: (total == 0)}

if total == 0:
  result = {discover: meta, empty: true, hint: "no candidates matched the terms; widen terms or drop file filters"}
else:
  meta_tokens = ceil(len(json_stringify(meta)) / 4)
  load_budget = mt - meta_tokens
  if load_budget < 1:
    error("working context: max_tokens too small for ranking metadata; need more than " + str(meta_tokens))
  refs = []
  for c in selected:
    refs = refs + [{f: c["f"], s: c["s"]}]
  manifest = {t: "discover " + join(" ", terms), v: "1.0", r: refs}
  res = lci.context(operation: "load", from_string: json_stringify(manifest), max_tokens: load_budget)
  if type(res) == "map" and has_key(res, "available") and res["available"] == false:
    error("working context: index unavailable: " + get(res, "reason", "") + " (" + get(res, "hint", "") + ")")
  if type(res) == "map" and has_key(res, "success") and res["success"] == false:
    error("working context: context load failed: " + get(res, "error", ""))
  budget = {requested: mt, ranking: meta_tokens, loader: load_budget}
  result = merge(res, {discover: merge(meta, {budget: budget})})

result

file = args["file"]
symbol = args["symbol"]
mt = get(args, "max_tokens", 8000)

if type(file) != "string" or len(file) == 0:
  error("working context: trace requires a non-empty file path")
if type(symbol) != "string" or len(symbol) == 0:
  error("working context: trace requires a non-empty symbol name")
if type(mt) != "int" or mt < 1:
  error("working context: max_tokens must be a positive integer")

expansions = ["callers", "references", "tests", "side_effects"]
meta = {selector: {file: file, symbol: symbol}, expansions: expansions}
meta_tokens = ceil(len(json_stringify(meta)) / 4)
load_budget = mt - meta_tokens
if load_budget < 1:
  error("working context: max_tokens too small for trace metadata; need more than " + str(meta_tokens))

manifest = {t: "trace " + file + " " + symbol, v: "1.0", r: [{f: file, s: symbol, x: expansions}]}
res = lci.context(operation: "load", from_string: json_stringify(manifest), max_tokens: load_budget)
if type(res) == "map" and has_key(res, "available") and res["available"] == false:
  error("working context: index unavailable: " + get(res, "reason", "") + " (" + get(res, "hint", "") + ")")
if type(res) == "map" and has_key(res, "success") and res["success"] == false:
  error("working context: context load failed: " + get(res, "error", ""))

resolved = true
if type(res) == "map" and has_key(res, "unresolved"):
  for u in res["unresolved"]:
    if get(u, "file", "") == file and get(u, "symbol", "") == symbol:
      resolved = false
trace = merge(meta, {resolved: resolved, budget: {requested: mt, ranking: meta_tokens, loader: load_budget}})
merge(res, {trace: trace})
